'use strict';
const $=id=>document.getElementById(id);let state,question=0,attempts=0,hits=0;
let mode=null;let nextTimer=null,audioContext=null;
function cancelAutoNext(){if(nextTimer!==null){clearTimeout(nextTimer);nextTimer=null;} $('next').innerHTML='次の問題 <span>→</span>';}
async function playResultSound(good){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioContext??=new Audio();if(audioContext.state==='suspended')await audioContext.resume();const now=audioContext.currentTime;const notes=good?[[660,0,.13],[880,.14,.22]]:[[155,0,.24],[125,.32,.46]];for(const [frequency,offset,duration] of notes){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=good?'sine':'sawtooth';osc.frequency.value=frequency;gain.gain.setValueAtTime(0,now+offset);gain.gain.linearRampToValueAtTime(good?.16:.13,now+offset+.015);if(!good){gain.gain.setValueAtTime(.13,now+offset+duration-.06);osc.frequency.linearRampToValueAtTime(frequency*.85,now+offset+duration);}gain.gain.exponentialRampToValueAtTime(.001,now+offset+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+offset);osc.stop(now+offset+duration+.02);osc.onended=()=>{osc.disconnect();gain.disconnect();};}}catch{/* Audio failure must never interrupt the quiz. */}}
const gcd=(a,b)=>b?gcd(b,a%b):a;
function frac(value){let n=Math.round(value*8),d=8,g=gcd(Math.abs(n),d);n/=g;d/=g;return d===1?String(n).replace('-','−'):`${n<0?'−':''}<span class="frac"><span>${Math.abs(n)}</span><span>${d}</span></span>`;}
const ri=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const shuffled=a=>{for(let i=a.length-1;i>0;i--){const j=ri(0,i);[a[i],a[j]]=[a[j],a[i]];}return a;};

function lineEquation(m,b){let term=m===0?'':(m===1?'':m===-1?'−':frac(m))+'x';if(b!==0)term+=(term?(b<0?' − ':' + '):(b<0?'−':''))+frac(Math.abs(b));return 'y = '+(term||'0');}
function makeQuestion(a,p,q,r,pair){const [name,u,v,letters]=[['AB',p,q,['p','q']],['BC',q,r,['q','r']],['AC',p,r,['p','r']]][pair];const area=Math.abs(a)*(q-p)*(r-q)*(r-p)/2,m=a*(u+v),b=-a*u*v;const wrongM=m!==0?-m:a*(v-u),wrongB=b!==0?-b:a,wrongArea=area*2;return {a,p,q,r,name,u,v,letters,m,b,answer:area,answered:false,options:shuffled([{m,b,area},{m:wrongM,b:wrongB,area},{m,b,area:wrongArea},{m:wrongM,b:wrongB,area:wrongArea}])};}
function begin(params){cancelAutoNext();if(!mode)return;if(mode==='parallel'){state=makeParallelQuestion();question++;renderParallel();return;}let a,p,q,r;if(params){({a,p,q,r}=params);}else{a=[.25,.5,1,2,3,-.25,-.5,-1,-2][ri(0,8)];p=ri(-5,0);q=p+ri(1,4);r=q+ri(1,4);}state=makeQuestion(a,p,q,r,ri(0,2));question++;render();}
function isCorrect(v){return v.m===state.m&&v.b===state.b&&v.area===state.answer;}
function render(){const {a,p,q,r,name,letters}=state;$('count').textContent='第'+question+'問';$('score').textContent='正解 '+hits+' 問 · 回答 '+attempts+' 問';$('equation').innerHTML='y = '+(a===1?'':a===-1?'−':frac(a))+'x²';$('question-title').innerHTML='直線 <em>'+name+'</em> の式と<br>三角形 <em>ABC</em> の面積は？';$('target-line').textContent='出題：直線 '+name;$('parameters').innerHTML=Object.entries({a,p,q,r}).map(([k,v])=>'<div class="parameter"><em>'+k+'</em><strong>'+frac(v)+'</strong></div>').join('');$('choices').innerHTML=state.options.map((v,i)=>'<button class="choice" data-i="'+i+'"><span class="key">'+(i+1)+'</span><span class="combination"><span class="choice-equation">'+lineEquation(v.m,v.b)+'</span><span class="choice-area">S = '+frac(v.area)+'</span></span></button>').join('');$('choices').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(Number(b.dataset.i)));$('feedback').innerHTML='<strong>直線の式と面積、両方を選ぶんだ！</strong><span>紫の直線 '+name+' に注目だぞ。</span>';$('formula').hidden=true;$('hint-toggle').setAttribute('aria-expanded','false');$('hint-toggle').innerHTML='2つの公式を見る <span>＋</span>';const [s,t]=letters;$('formula').innerHTML='<div class="math">'+name+'：y = a('+s+' + '+t+')x − a'+s+t+'</div><p>傾きは「a × 和」、切片は「−a × 積」</p><div class="math">S = '+frac(.5)+'|a|(q − p)(r − q)(r − p)</div><p>面積は「半分 × |a| × 3つの差」</p>';draw();}
function answer(i){if(!mode)return;if(mode==='parallel'){answerParallel(i);return;}if(state.answered||!Number.isInteger(i)||i<0||i>3)return;state.answered=true;attempts++;const good=isCorrect(state.options[i]);if(good)hits++;void playResultSound(good);$('choices').querySelectorAll('button').forEach((b,j)=>{b.disabled=true;if(isCorrect(state.options[j]))b.classList.add('correct');else if(j===i)b.classList.add('wrong');});const {a,p,q,r,u,v,m,b,name,answer:ans}=state;const par=n=>'('+frac(n)+')';$('feedback').innerHTML='<strong>'+(good?'正解！ 1.5秒後に次の問題だ！':'おしい！ 緑の組み合わせが正解だぞ。')+'</strong><div class="explain-line">傾き：'+frac(a)+' × ('+frac(u)+' + '+par(v)+') = '+frac(m)+'<br>切片：−'+par(a)+' × '+par(u)+' × '+par(v)+' = '+frac(b)+'</div><div class="calculation">S = '+frac(.5)+' × '+frac(Math.abs(a))+' × '+(q-p)+' × '+(r-q)+' × '+(r-p)+' = '+frac(ans)+'</div>';$('score').textContent='正解 '+hits+' 問 · 回答 '+attempts+' 問';if(good){$('next').innerHTML='次の問題へ進む… <span>→</span>';nextTimer=setTimeout(()=>{nextTimer=null;begin();},1500);}}
function draw(){const {a,p,q,r}=state;const lo=Math.min(p,0)-1,hi=Math.max(r,0)+1;const maxY=Math.max(a*p*p,a*q*q,a*r*r,0),minY=Math.min(a*p*p,a*q*q,a*r*r,0);const range=maxY-minY||1;const ymin=minY-range*.15,ymax=maxY+range*.18;const X=x=>65+(x-lo)/(hi-lo)*630,Y=y=>465-(y-ymin)/(ymax-ymin)*400;const ya=a*p*p,yb=a*q*q,yc=a*r*r,yd=a*((p+r)*q-p*r);const line=(x1,y1,x2,y2,attrs='')=>`<line x1="${X(x1)}" y1="${Y(y1)}" x2="${X(x2)}" y2="${Y(y2)}" ${attrs}/>`;let out='<defs><clipPath id="clip"><rect x="35" y="30" width="690" height="460"/></clipPath></defs>';for(let x=Math.ceil(lo);x<=hi;x++)out+=line(x,ymin,x,ymax,'stroke="#edf1f6"');for(let i=0;i<=8;i++){const y=ymin+(ymax-ymin)*i/8;out+=line(lo,y,hi,y,'stroke="#f1f4f8"');}out+=line(lo,0,hi,0,'stroke="#8391a6" stroke-width="1.5"')+line(0,ymin,0,ymax,'stroke="#8391a6" stroke-width="1.5"');out+=`<text x="${X(hi)+10}" y="${Y(0)+6}" class="axis">x</text><text x="${X(0)-5}" y="${Y(ymax)-12}" class="axis">y</text>`;out+=`<g clip-path="url(#clip)"><polygon points="${X(p)},${Y(ya)} ${X(q)},${Y(yb)} ${X(r)},${Y(yc)}" fill="#ffb34d" fill-opacity=".24" stroke="#c3883c" stroke-width="2"/>`;let path='';for(let i=0;i<=400;i++){const x=lo+(hi-lo)*i/400;path+=`${i?'L':'M'}${X(x)},${Y(a*x*x)} `;}out+=`<path d="${path}" fill="none" stroke="#526ee7" stroke-width="3"/>`+line(p,ya,r,yc,'stroke="#d78a32" stroke-width="2"')+line(q,yb,q,yd,'stroke="#14967d" stroke-width="2" stroke-dasharray="6 5"')+line(lo,state.m*lo+state.b,hi,state.m*hi+state.b,'stroke="#9561ce" stroke-width="3.5"')+'</g>';for(const [name,x,y,symbol] of [['A',p,ya,'p'],['B',q,yb,'q'],['C',r,yc,'r']]){out+=line(x,0,x,y,'stroke="#9ba6b7" stroke-dasharray="4 5"');out+=`<circle cx="${X(x)}" cy="${Y(y)}" r="6" fill="#192943"/><text x="${X(x)+(name==='A'?-25:12)}" y="${Y(y)+(name==='B'?(a>0?-14:25):(a>0?-14:25))}" class="point">${name}</text><text x="${X(x)}" y="${Y(0)+(a>0?38:-20)}" text-anchor="middle" class="tick">${x}</text>`;}out+=`<circle cx="${X(q)}" cy="${Y(yd)}" r="5" fill="#14967d"/><text x="${X(q)+12}" y="${Y(yd)+(a>0?-12:26)}" class="point" fill="#14967d">D</text><style>.point{font:italic 25px Georgia,serif}.tick{font:600 32px Georgia,serif;fill:#40516c}.axis{font:italic 22px Georgia,serif;fill:#62718a}</style>`;$('graph').innerHTML=out; $('graph').setAttribute('aria-label',`y = ${a} x二乗。Aのx座標${p}、Bのx座標${q}、Cのx座標${r}。三角形ABCを表示。`);}
$('next').onclick=()=>begin();$('hint-toggle').onclick=()=>{const show=$('formula').hidden;$('formula').hidden=!show;$('hint-toggle').setAttribute('aria-expanded',String(show));$('hint-toggle').innerHTML=show?'公式を隠す <span>−</span>':(mode==='parallel'?'平行の公式を見る <span>＋</span>':'2つの公式を見る <span>＋</span>');};$('edit').onclick=()=>{cancelAutoNext();$('custom-form').hidden=!$('custom-form').hidden;if(!$('custom-form').hidden){for(const k of ['a','p','q','r'])$(k+'-input').value=state[k];$('error').textContent='';}};
$('custom-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(['a','p','q','r'].map(k=>[k,Number($(k+'-input').value)]));if(![.25,.5,1,2,3,-.25,-.5,-1,-2,-3].includes(v.a)||![v.p,v.q,v.r].every(n=>Number.isInteger(n)&&n>=-8&&n<=8)||!(v.p<v.q&&v.q<v.r)){$('error').textContent='p < q < r になるように、−8〜8の整数を入れてくれ。';return;}$('custom-form').hidden=true;begin(v);};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName)||!$('custom-form').hidden)return;if(e.key.toLowerCase()==='f'){e.preventDefault();toggleFullscreen();return;}if(['1','2','3','4'].includes(e.key))answer(Number(e.key)-1);if(e.key==='Enter'){e.preventDefault();begin();}});
showModes();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_area_question',description:'Start a new random area quiz question, replacing the current question.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('No parameters accepted');if(mode!=='area')selectMode('area');else begin();return {a:state.a,p:state.p,q:state.q,r:state.r,line:state.name,question};}})).catch(()=>{});}catch{}}

function syncFullscreenButton(){const isFull=!!document.fullscreenElement;const btn=$('fullscreen-toggle');if(!btn)return;btn.setAttribute('aria-pressed',String(isFull));btn.innerHTML=isFull?'<span class="fs-icon">✖</span> 解除':'<span class="fs-icon">⛶</span> 全画面';}
function toggleFullscreen(){if(!document.fullscreenElement){document.documentElement.requestFullscreen().catch(()=>{});}else{document.exitFullscreen().catch(()=>{});}}
$('fullscreen-toggle').onclick=toggleFullscreen;
document.addEventListener('fullscreenchange',syncFullscreenButton);
syncFullscreenButton();

function syncThemeButton(){const dark=document.documentElement.dataset.theme==='dark';$('theme-toggle').setAttribute('aria-pressed',String(dark));$('theme-toggle').textContent=dark?'☀ ライトモード':'☾ ダークモード';}
$('theme-toggle').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('parabola-theme',theme);}catch{}syncThemeButton();};syncThemeButton();

function showModes(){cancelAutoNext();mode=null;document.querySelector('.workspace').hidden=true;$('mode-picker').hidden=false;$('mode-menu').hidden=true;$('count').hidden=true;$('score').hidden=true;document.querySelector('footer').hidden=true;}
function selectMode(selected){mode=selected;question=0;attempts=0;hits=0;$('mode-picker').hidden=true;document.querySelector('.workspace').hidden=false;$('mode-menu').hidden=false;$('count').hidden=false;$('score').hidden=false;document.querySelector('footer').hidden=false;$('custom-form').hidden=true;const parallel=mode==='parallel';document.querySelector('.custom').hidden=parallel;$('parameters').classList.toggle('parallel-parameters',parallel);document.querySelector('.panel-top .eyebrow').textContent=parallel?'放物線上の4点':'放物線上の3点';document.querySelector('.quiz-panel .eyebrow').textContent=parallel?'PARALLEL QUIZ':'LINE & AREA QUIZ';document.querySelector('.intro').textContent=parallel?'x座標と、AB・CDに共通する傾きを選ぼう。':'直線の式と面積の組み合わせを選ぼう。';document.querySelector('.legend').innerHTML=parallel?'<span><i class="blue"></i>放物線</span><span><i class="orange"></i>直線 AB</span><span><i class="purple"></i>直線 CD</span>':'<span><i class="blue"></i>放物線</span><span><i class="orange"></i>三角形 ABC</span><span><i class="purple"></i><b id="target-line"></b></span>';document.querySelector('footer span').textContent=parallel?'AB ∥ CD ｜ 4点は同じ放物線上':'p < q < r ｜ a が負でも面積は正';begin();}
function makeParallelQuestion(){const a=[.5,1,1.5,2][ri(0,3)],A=-ri(1,3),B=ri(Math.abs(A)+1,6),gap=ri(2,3);const points={A,B,C:A-gap,D:B+gap};const missing=['A','B','C','D'][ri(0,3)],answer=points[missing];const slope=a*(A+B),wrongX=answer+(answer<0?-1:1),wrongSlope=a*(B-A);const options=shuffled([{x:answer,slope},{x:wrongX,slope},{x:answer,slope:wrongSlope},{x:wrongX,slope:wrongSlope}]);return {a,points,missing,answer,slope,options,answered:false};}
function renderParallel(){const {a,missing,options}=state;$('count').textContent='第'+question+'問';$('score').textContent='正解 '+hits+' 問 · 回答 '+attempts+' 問';$('equation').innerHTML='y = '+(a===1?'':frac(a))+'x²';$('question-title').innerHTML='AB ∥ CD のとき<br>点 <em>'+missing+'</em> のx座標と傾きは？';$('parameters').innerHTML='<div class="parameter"><em>a</em><strong>'+frac(a)+'</strong></div><div class="parameter"><strong>AB ∥ CD</strong></div>';$('choices').innerHTML=options.map((v,i)=>'<button class="choice parallel-pair" data-i="'+i+'"><span class="key">'+(i+1)+'</span><span class="combination"><span>x = '+frac(v.x)+'</span><span class="choice-area">傾き '+frac(v.slope)+'</span></span></button>').join('');$('choices').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(Number(b.dataset.i)));$('feedback').innerHTML='<strong>平行な直線は、傾きが同じだ！</strong><span>残りのx座標と、共通の傾きを求めよう。</span>';$('formula').hidden=true;$('hint-toggle').setAttribute('aria-expanded','false');$('hint-toggle').innerHTML='平行の公式を見る <span>＋</span>';$('formula').innerHTML='<p>A・B・C・Dのx座標をそれぞれ u・v・s・t とすると</p><div class="math">a(u + v) = a(s + t)</div><div class="math">u + v = s + t</div><div class="math">傾き = a(u + v) = a(s + t)</div><p>平行なら「両端のx座標の和」が等しいぞ！</p>';drawParallel();}
function answerParallel(i){if(state.answered||!Number.isInteger(i)||i<0||i>3)return;state.answered=true;attempts++;const correct=v=>v.x===state.answer&&v.slope===state.slope;const good=correct(state.options[i]);if(good)hits++;void playResultSound(good);$('choices').querySelectorAll('button').forEach((b,j)=>{b.disabled=true;if(correct(state.options[j]))b.classList.add('correct');else if(j===i)b.classList.add('wrong');});const {points:p,missing:k,answer:ans}=state;const other={A:['C','D','B'],B:['C','D','A'],C:['A','B','D'],D:['A','B','C']}[k];const term=n=>n<0?'('+frac(n)+')':frac(n);$('feedback').innerHTML='<strong>'+(good?'正解！ 1.5秒後に次の問題だ！':'おしい！ 緑の組み合わせが正解だぞ。')+'</strong><div class="explain-line">Aのx座標 ＋ Bのx座標<br>＝ Cのx座標 ＋ Dのx座標</div><div class="calculation">'+k+'：'+term(p[other[0]])+' ＋ '+term(p[other[1]])+' − '+term(p[other[2]])+' = '+frac(ans)+'</div><div class="calculation">傾き：'+frac(state.a)+' × ('+term(p.A)+' ＋ '+term(p.B)+') = '+frac(state.slope)+'</div>';$('score').textContent='正解 '+hits+' 問 · 回答 '+attempts+' 問';drawParallel();if(good){$('next').innerHTML='次の問題へ進む… <span>→</span>';nextTimer=setTimeout(()=>{nextTimer=null;begin();},1500);}}
function drawParallel(){const {a,points,missing,answered}=state;const {A,B,C,D}=points,lo=C-1,hi=D+1,ymax=2*Math.max(C*C,D*D)*1.15;const X=x=>65+(x-lo)/(hi-lo)*630,Y=y=>440-y/ymax*365;const line=(x1,y1,x2,y2,style)=>`<line x1="${X(x1)}" y1="${Y(y1)}" x2="${X(x2)}" y2="${Y(y2)}" ${style}/>`;let svg='<defs><clipPath id="parallel-clip"><rect x="35" y="28" width="690" height="460"/></clipPath></defs>';svg+=line(lo,0,hi,0,'stroke="#8391a6" stroke-width="1.5"')+line(0,-ymax*.1,0,ymax,'stroke="#8391a6" stroke-width="1.5"');svg+=`<text x="${X(hi)+10}" y="${Y(0)+6}" class="axis">x</text><text x="${X(0)-8}" y="${Y(ymax)-12}" class="axis">y</text><text x="${X(0)-15}" y="${Y(0)+28}" class="axis">0</text><g clip-path="url(#parallel-clip)">`;let path='';for(let i=0;i<=400;i++){const x=lo+(hi-lo)*i/400;path+=(i?'L':'M')+X(x)+','+Y(a*x*x)+' ';}svg+='<path d="'+path+'" fill="none" stroke="#526ee7" stroke-width="3"/>';for(const [u,v,color] of [[A,B,'#d78a32'],[C,D,'#9561ce']]){const slope=a*(u+v),b=-a*u*v;svg+=line(lo,slope*lo+b,hi,slope*hi+b,`stroke="${color}" stroke-width="3"`);}svg+='</g>';for(const [name,x] of Object.entries(points)){const y=a*x*x;svg+=line(x,0,x,y,'stroke="#9ba6b7" stroke-dasharray="5 5"');svg+=`<circle cx="${X(x)}" cy="${Y(y)}" r="6" fill="#192943"/><text x="${X(x)+(x<0?-28:13)}" y="${Y(y)-12}" class="point">${name}</text><text x="${X(x)}" y="${Y(0)+40}" text-anchor="middle" class="tick">${name===missing&&!answered?'？':String(x).replace('-','−')}</text>`;}svg+='<style>.point{font:italic 28px Georgia,serif}.tick{font:600 32px Georgia,serif;fill:#40516c}.axis{font:italic 22px Georgia,serif;fill:#62718a}</style>';$('graph').innerHTML=svg;$('graph').setAttribute('aria-label','放物線上の4点。ABとCDは平行。'+Object.entries(points).map(([k,x])=>k+'のx座標は'+(k===missing&&!answered?'不明':x)).join('、'));}
$('choose-area').onclick=()=>selectMode('area');$('choose-parallel').onclick=()=>selectMode('parallel');$('mode-menu').onclick=showModes;
